def normalize_legacy_age_bands(apps, schema_editor):
    """Reclassify school profiles from official roster DOB; never infer public age."""
    LearningProfile = apps.get_model("learning", "LearningProfile")
    LearningProject = apps.get_model("learning", "LearningProject")
    Student = apps.get_model("schools", "Student")
    db_alias = schema_editor.connection.alias
    today = timezone.localdate()
    verified_at = timezone.now()

    for profile in LearningProfile.objects.using(db_alias).all().iterator():
        band = profile.age_band
        verified = False
        if profile.account_kind == "school_student" and profile.student_id:
            dob = Student.objects.using(db_alias).filter(pk=profile.student_id).values_list(
                "date_of_birth", flat=True,
            ).first()
            age = None
            if isinstance(dob, date):
                age = today.year - dob.year - ((today.month, today.day) < (dob.month, dob.day))
                if age < 0 or age > 120:
                    age = None
            if age is None:
                band = "unknown"
            elif age < 10:
                band = "under_10"
            elif age < 18:
                band = "10_17"
            else:
                band = "adult"
            verified = age is not None
        elif band == "under_13":
            # The old band cannot distinguish under-10 from age 10–12.
            band = "unknown"
        elif band == "13_17":
            band = "10_17"

        profile.age_band = band
        if verified:
            profile.age_verified_at = verified_at
            profile.age_verification_source = "school_roster"
        profile.save(update_fields=["age_band", "age_verified_at", "age_verification_source"])

    for project in LearningProject.objects.using(db_alias).all().iterator():
        if project.age_band == "under_13":
            project.age_band = "unknown"
            project.save(update_fields=["age_band"])
        elif project.age_band == "13_17":
            project.age_band = "10_17"
            project.save(update_fields=["age_band"])


def reverse_legacy_age_bands(apps, schema_editor):
    LearningProfile = apps.get_model("learning", "LearningProfile")
    LearningProject = apps.get_model("learning", "LearningProject")
    db_alias = schema_editor.connection.alias
    for model in (LearningProfile, LearningProject):
        for row in model.objects.using(db_alias).all().iterator():
            if row.age_band == "under_10":
                row.age_band = "under_13"
                row.save(update_fields=["age_band"])
            elif row.age_band == "10_17":
                row.age_band = "13_17"
                row.save(update_fields=["age_band"])


